<div class="cols"><div class="stack">
<section class="apanel"><h2>Predefined segments</h2><?php foreach (\App\Services\LoyaltyReports::SEGMENTS as $k => $l): ?><div class="ph" style="margin:0 0 8px"><a href="<?= e(url('admin/loyalty/segments?segment=' . $k)) ?>" class="<?= $key === $k ? 'lime' : '' ?>"><?= e($l) ?></a><b><?= (int) $counts[$k] ?></b></div><?php endforeach; ?></section>
<?php if ($saved->count()): ?><section class="apanel"><h2>Saved segments</h2><?php foreach ($saved as $sg): ?><div class="ph" style="margin:0 0 8px"><a href="<?= e(url('admin/loyalty/segments?segment=saved:' . $sg->id)) ?>"><?= e($sg->name) ?></a><?php if (auth()->user()->isAdmin()): ?><form method="post" action="<?= e(url('admin/loyalty/segments/' . $sg->id . '/delete')) ?>"><?= csrf_field() ?><button class="btn sm ghost danger" data-confirm="Delete segment?">✕</button></form><?php endif; ?></div><?php endforeach; ?></section><?php endif; ?>
