  <div class="g2"><?= field_text('min_spend', 'Min lifetime spend', $rules['min_spend'] ?? '', ['type' => 'number', 'step' => '0.01']) ?><?= field_text('min_orders', 'Min orders', $rules['min_orders'] ?? '', ['type' => 'number']) ?></div>
  <div class="g2"><?= field_text('inactive_days', 'No order for ≥ days', $rules['inactive_days'] ?? '', ['type' => 'number']) ?><?= field_text('active_days', 'Ordered within days', $rules['active_days'] ?? '', ['type' => 'number']) ?></div>
  <button class="btn">Preview</button></form>
  <?php if ($key === 'custom' && auth()->user()->isAdmin()): ?><form method="post" action="<?= e(url('admin/loyalty/segments/save')) ?>" style="margin-top:12px"><?= csrf_field() ?><?php foreach ($rules as $k => $v): ?><input type="hidden" name="<?= e($k) ?>" value="<?= e($v) ?>"><?php endforeach; ?><?= field_text('name', 'Save this segment as', '', ['required' => true]) ?><button class="btn ghost">Save segment</button></form><?php endif; ?></section>
</div><div class="stack">
<?php if ($run): ?><section class="apanel"><div class="ph"><h2><?= number_format($total) ?> customer(s)</h2><span><a class="btn sm ghost" href="<?= e(url('admin/loyalty/segments?' . http_build_query(request()->query() + ['export' => 'csv']))) ?>">CSV</a> <a class="btn sm ghost" href="<?= e(url('admin/loyalty/segments?' . http_build_query(request()->query() + ['export' => 'xls']))) ?>">Excel</a></span></div>
  <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Customer</th><th class="r">Points</th><th class="r">Spend</th><th class="r">Orders</th><th>Last order</th><th>Suggestion</th></tr></thead><tbody>
  <?php foreach ($members as $m): $rec = \App\Services\LoyaltyReports::recommend($m); ?><tr><td><b><a href="<?= e(url('admin/loyalty/members/' . $m->id)) ?>"><?= e($m->name) ?></a></b><small><?= e($m->email) ?></small></td><td class="r"><?= number_format($m->points) ?></td><td class="r"><?= money($m->spend) ?></td><td class="r"><?= (int) $m->orders_n ?></td><td class="muted"><?= $m->last_order ? e(fmt_date($m->last_order, false)) : '—' ?></td>
