  <div class="g3"><?= field_select('act', 'Action', ['award' => 'Award points', 'reward' => 'Assign a reward'], 'award') ?><?= field_text('amount', 'Points', '', ['type' => 'number', 'min' => '1']) ?><?= field_select('reward_id', 'Reward', ['' => '—'] + array_column(array_map(fn ($r) => (array) $r, $rewards), 'name', 'id'), '') ?></div><?= field_text('reason', 'Reason', '', ['placeholder' => 'Win-back campaign…']) ?><button class="btn" data-confirm="Apply to all <?= (int) $total ?> customers?">Apply to <?= (int) $total ?> customers</button></form></section><?php endif; ?>
